const Fonts::EcamValue16::Glyph& Fonts::EcamValue16::GetGlyph(char character) {
    switch (character) {
        case ' ':   return EcamValue16Glyph_32;
		case '-':	return EcamValue16Glyph_45;
		case '.':	return EcamValue16Glyph_46;
		case '0':	return EcamValue16Glyph_48;
		case '1':	return EcamValue16Glyph_49;
		case '2':	return EcamValue16Glyph_50;
		case '3':	return EcamValue16Glyph_51;
		case '4':	return EcamValue16Glyph_52;
		case '5':	return EcamValue16Glyph_53;
		case '6':	return EcamValue16Glyph_54;
		case '7':	return EcamValue16Glyph_55;
		case '8':	return EcamValue16Glyph_56;
		case '9':	return EcamValue16Glyph_57;
		case 'P':	return EcamValue16Glyph_80;
		case 'R':	return EcamValue16Glyph_82;
		case 'N':	return EcamValue16Glyph_78;
		case 'D':	return EcamValue16Glyph_68;
		case 'M':	return EcamValue16Glyph_77;
        default:    return EcamValue16Glyph_Error;
    }
}

